import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';
import { gsap } from 'gsap';

/**
 * @param {Object} config - Node configuration object.
 * @param {Object} ctx - Node context providing loaders and primitives.
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const root = new THREE.Object3D();
  root.position.set(
    config.position?.x ?? -3.2,
    config.position?.y ?? 1,
    config.position?.z ?? 0.06
  );
  root.rotation.set(
    config.rotation?.x ?? 0,
    config.rotation?.y ?? 0,
    config.rotation?.z ?? 0
  );
  root.scale.set(
    config.scale?.x ?? 1,
    config.scale?.y ?? 1,
    config.scale?.z ?? 1
  );

  // ---------- Main textured plane ----------
  const imageTex = ctx.textureLoader.load(
    config.assets?.imageUrl ||
      '/prism-mock/home/nodes/cta-hero-isolated.png'
  );

  const planeGeo = new THREE.PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({
    map: imageTex,
    transparent: true,
  });

  const planeMesh = new THREE.Mesh(planeGeo, planeMat);
  planeMesh.position.set(0, 0, 0);
  root.add(planeMesh);

  // ---------- Text overlay ----------
  // Expecting an atlas texture at index 0
  const atlasTex = ctx.fontAtlas[0];
  const textGeo = new THREE.PlaneGeometry(1, 1);
  const textMat = new MeshBasicNodeMaterial({
    map: atlasTex,
    transparent: true,
  });

  // Apply UV transform based on source rect (0,0,512,320) -> full texture
  // If a different rect were required, adjust offset/repeat here.
  if (atlasTex) {
    const source = config.atlas?.sourceRect ?? { x: 0, y: 0, w: 512, h: 320 };
    const atlasSize = { w: atlasTex.image?.width || 512, h: atlasTex.image?.height || 320 };
    textMat.map.offset.set(source.x / atlasSize.w, 1 - (source.y + source.h) / atlasSize.h);
    textMat.map.repeat.set(source.w / atlasSize.w, source.h / atlasSize.h);
    textMat.map.needsUpdate = true;
  }

  const textMesh = new THREE.Mesh(textGeo, textMat);
  textMesh.position.set(0, 0, 0.001); // slight offset to avoid z‑fighting
  root.add(textMesh);

  // ---------- Handlers & cleanup ----------
  root.userData.handlers = {};

  root.userData.cleanup = () => {
    // Dispose of materials & geometries (textures are cached, do not dispose)
    planeMat.dispose();
    planeGeo.dispose();
    textMat.dispose();
    textGeo.dispose();

    // Kill any GSAP timelines associated with this node (none in this node, but safe)
    gsap.globalTimeline.killTweensOf(root);
  };

  // Apply any cinematic primitives listed in config (none for this node)
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        fn(root, prim.params);
      }
    }
  }

  return root;
}
